    tags: { examTarget: "RN", clientNeed: "physiological-integrity", subCategory: "pharmacological-and-parenteral-therapies", integratedProcess: "nursing-process", cjmmStep: "prioritize-hypotheses", bodySystem: "multisystem", contentTopic: "pca-opioid", specialty: "med-surg" },
