    tags: { examTarget: "RN", clientNeed: "physiological-integrity", subCategory: "physiological-adaptation", integratedProcess: "clinical-judgment", cjmmStep: "take-actions", bodySystem: "respiratory", contentTopic: "co-poisoning", specialty: "med-surg" },
